/* 工具1：固定密钥 DES/CBC 加密（用于登录密码、签名 body） */
function encode(data){
  return String(java.createSymmetricCrypto("DES/CBC/PKCS5Padding", "KEY_HERE", "IV_HERE").encryptBase64(String(data)));
}

/* 工具2：登录头读取（兼容 Rhino/Jetpack 两种框架） */
function getHdr(k){
  try {
    return String(source.getLoginHeaderMap().get(k) || "");
  } catch(e){
    var m = JSON.parse(String(source.getLoginHeader()||"#{}").replace(/^#/,''));
    return m[k] || "";
  }
}

/* 工具3：登录头写入（支持批量设置多 key=value） */
function setHeaders(){
  var map;
  try { map = source.getLoginHeaderMap(); } catch(e){
    map = JSON.parse(String(source.getLoginHeader()||"#{}").replace(/^#/,''));
  }
  for (var i=0; i<arguments.length; i++){
    var k = arguments[i].split("=")[0];
    var v = arguments[i].split("=")[1];
    if (typeof map.put === "function") map.put(k, v);
    else map[k] = v;
  }
  // 转 JSON 写回
  var obj = {};
  if (typeof map.forEach === "function") map.forEach((kk,vv)=>obj[kk]=vv);
  else obj = map;
  source.putLoginHeader("#"+JSON.stringify(obj));
}

/* 工具4：data: URL ↔ 真实 URL 互转（用于 tocUrl 自销毁设计） */
function packToDataUrl(params){
  return 'data:token;base64,' + java.base64Encode(params) + ',{"type":"mypack"}';
}
function unpackDataUrl(d){
  if (/^http/.test(d)) return d;
  return String(java.base64Decode(String(d).match(/base64,([^,]+),*/)[1]));
}

/* 工具5：响应头派生密钥反爬（VIP 章节专用） */
function decryptFromHeader(rawBody, ak, ks){
  if (!ak || !ks || !rawBody) return null;
  var v6 = ak.charCodeAt(ak.length-1);
  var v9 = 0; for (var i=0;i<ak.length;i++) v9 += ak.charCodeAt(i);
  var v15 = v9 % ks.length, v17 = Math.floor(v9/65);
  var v43 = ks.substring(v15, Math.min(v17+v15, ks.length));
  var v38, dest;
  if ((v6 & 1) !== 0) { v38 = rawBody.slice(-12); dest = rawBody.slice(0,-12); }
  else                 { v38 = rawBody.slice(0,12); dest = rawBody.slice(12); }
  var key = String(java.md5Encode(v43+v38)).slice(0,8);
  var iv  = String(java.md5Encode(v38)).slice(0,8);
  return String(java.createSymmetricCrypto("DES/CBC/PKCS5Padding", key, iv).decryptStr(dest));
}

/* 工具6：智能判断响应是否为密文 */
function isRawCipher(b){
  return b && b.length>60 && !/^\s*\{/.test(b) && b.indexOf('"content"')<0 && b.indexOf('"message"')<0;
}

