/* === 账密登录（带设备验证自动重试） === */
function guessCheckType(account){
  return /@/.test(String(account)) ? "email" : "phone";
}
function doLoginOnce(account, password, checktype, code){
  var en = encode(password);
  var now = String(Date.now());
  var id = ("846"+now+"4893")+":"+java.androidId()+"d4:";
  var sign = encode(now+"_"+"_");
  var url = "https://example.com/api/login?versionCode=1"
    +"&loginName="+encodeURIComponent(account)
    +"&encode=1&loginPassword="+encodeURIComponent(en)
    +"&sign="+encodeURIComponent(sign)
    +"&identifiers="+encodeURIComponent(id)
    +"&autologin=1";
  if (checktype && code) url += "&checktype="+checktype+"&checkdevicecode="+encodeURIComponent(code);
  var r = String(java.ajax(url));
  try { return JSON.parse(r); } catch(e){ return {"code":"-1","message":r.slice(0,120)}; }
}
function loginByPassword(){
  try {
    var account = String(result.get("账号")||"").replace(/\s/g,"");
    var password = String(result.get("密码")||"");
    if (!account || !password) { java.longToast("请先填写账号密码"); return; }
    var code = String(result.get("验证码（可留空，触发验证时自动重试）")||"").replace(/\s/g,"");
    var ct = guessCheckType(account);

    var d = code ? doLoginOnce(account, password, ct, code) : doLoginOnce(account, password, null, null);
    if (d.token) { setHeaders("token="+d.token); java.longToast("登录成功"); return; }

    /* 设备验证自动重试（核心 7 行） */
    if (d.code==="6018" || d.code==="221003" || /请校验验证码/.test(String(d.message||""))) {
      var useCode = code || "000000";
      var d2 = doLoginOnce(account, password, ct, useCode);
      if (d2.token) { setHeaders("token="+d2.token); java.longToast("登录成功（已自动通过设备验证）"); return; }
      var ct2 = (ct=="phone") ? "email" : "phone";
      var d3 = doLoginOnce(account, password, ct2, useCode);
      if (d3.token) { setHeaders("token="+d3.token); java.longToast("登录成功（已自动通过设备验证-"+ct2+"）"); return; }
    }
    java.longToast("登录失败："+(d.message||JSON.stringify(d).slice(0,150)));
  } catch(e){ java.log(e); java.toast("账密登录异常："+e); }
}

/* === 扫码登录（data: URL 渲染） === */
function toScan(){
  try {
    var e = java.ajax("https://example.com/api/scanCodeLogin?versionCode=1");
    var d = JSON.parse(e).data;
    var scanUrl = "https://target.com/scan?key="+d.key;
    var html = "<title>扫码登录</title><meta name=\"viewport\" content=\"width=device-width\">"
      +"<p>请用 App 扫码</p>"
      +"<img style=\"width:300px\" src=\"https://api.qrtool.cn/?text="+encodeURIComponent(scanUrl)+"\">"
      +"<p>扫码后点右上角 ✓</p>";
    var u = java.startBrowserAwait("data:text/html;base64,"+java.base64Encode(html), "扫码登录", false).body();
    if (u) {
      var post = {"method":"POST","body":encode(JSON.stringify({key:d.key})),"headers":{"Content-Type":"application/octet-stream"}};
      var t = JSON.parse(String(java.ajax("https://example.com/api/checkScan,"+JSON.stringify(post))));
      if (t.data && t.data.token) { setHeaders("token="+t.data.token); java.toast("登录成功"); }
      else java.toast(t.message);
    }
  } catch(e){ java.log(e); java.toast("扫码登录失败"); }
}

function toLogout(){ setHeaders("token="); java.toast("已清除登录"); }

