ruleContent.payAction:
var params = unpackDataUrl(baseUrl);
var bid = (params.match(/bookId=(\d+)/)||["",""])[1];
var cid = (params.match(/chapterId=(\d+)/)||["",""])[1];
var token = getHdr('token');
if (!/^\d+_[\w\d]{16,}/.test(token)) {
  java.longToast("❌ 尚未登录\n请先登录后再购买");
  result = false;
} else {
  /* 余额预查（失败不阻断） */
  var balMsg = "";
  try {
    var bSign = encode(String(Date.now())+':'+token);
    var bUrl = "https://example.com/api/getBalance?token="+token+"&sign="+encodeURIComponent(bSign);
    var bJ = JSON.parse(String(java.ajax(bUrl)));
    var bal = bJ.balance ?? bJ.data?.balance;
    if (bal !== undefined && bJ.code !== "1004") balMsg = "💰 当前余额："+bal+"\n";
  } catch(eb){}

  /* 购买 */
  try {
    var enbody = String(Date.now())+':'+token+':'+bid;
    var sign = encode(enbody);
    var url = "https://example.com/api/buy?versionCode=1&bookId="+bid+"&chapters="+cid+"&sign="+encodeURIComponent(sign);
    var r = JSON.parse(String(java.ajax(url)));
    var msg = String(r.message||"");
    if (/成功/.test(msg)) {
      java.longToast("✅ "+msg+"\n"+balMsg);
      result = true;
    } else if (r.code==="1004" || /登入验证失败/.test(msg)) {
      java.longToast("❌ 登录已过期，请重新登录");
      result = false;
    } else if (/余额/.test(msg) || /不足/.test(msg)) {
      java.longToast("❌ "+balMsg+msg);
      result = false;
    } else {
      java.longToast("❌ "+(msg||"购买失败"));
      result = false;
    }
  } catch(e){
    java.longToast("❌ 购买异常："+e);
    result = false;
  }
}
